    if not text:
        return {}

    # Regex to match fenced code blocks with optional language and optional path hint
    # Pattern: ```[language] [path]\n content \n```
    # We look for blocks that might contain a path in the info string or just assume sequential naming if not present.
    # The spec says "path->content map". Usually, agents write ```python path/to/file.py ... ```

    pattern = r"```(?:\w+)?\s+([^\n]+)\n(.*?)```"
    matches = re.findall(pattern, text, re.DOTALL)

    bundle = {}
    for i, (path_hint, content) in enumerate(matches):
        # Clean up path hint
        path = path_hint.strip()
        # Remove potential markdown artifacts from path if any
        path = sanitize_path(path)

        # If path looks like a filename, use it. Otherwise, generate a name.
        if not path or '/' not in path and '.' not in path:
            # Try to detect if it's just a language tag that got captured?
            # The regex captures everything after the backticks until newline.
            # If the capture is just "python", it's not a path.
            if path in ['python', 'py', 'bash', 'sh', 'json', 'yaml', 'toml']:
