        """Morphs an existing genome by adding, pruning, or reshaping departmental pods.

        Invariants:
          1. Deep-copy isolation: Must never mutate `parent` in-place. `child.code_overlays`
             must be an independent copy of `parent.code_overlays`.
          2. Lineage: Sets `child.company_id = child_id`, `child.generation = target_generation`,
             `child.parent_ids = [parent.company_id]`, and appends `mutation_name` to
             `child.mutation_history`.
          3. Tool enablement: Any newly spawned technical department (`formal_verification`,
             `systems_eng`, `qa_testing`, `ai_acceleration`) must set `tools_enabled=True` on
             its worker `AgentGenome` instances so they can write files.
          4. Protected pods: Must retain at least 2 departments and must never prune
             `dept_systems_eng` or `dept_qa_redteam`.
        """
        # 1. Deep-copy isolation
        child = parent.copy()

        # 2. Lineage
        child.company_id = child_id
        child.generation = target_generation
        child.parent_ids = [parent.company_id]
        child.mutation_history = list(child.mutation_history) + [mutation_name]

        # Ensure code_overlays is an independent copy (already handled by copy(), 
        # but explicit for clarity if copy() implementation changes)
        child.code_overlays = dict(parent.code_overlays)

        # 4. Protected pods: Ensure we retain at least 2 departments and protected ones
        # Identify protected departments
        protected_depts = [
            d for d in child.departments 
            if d.dept_id in PROTECTED_DEPT_IDS
        ]

        # If we have fewer than 2 departments, we need to add some
        # If we are missing protected departments, we need to add them

        current_dept_ids = {d.dept_id for d in child.departments}

        # Ensure protected departments exist
        for protected_id in PROTECTED_DEPT_IDS:
            if protected_id not in current_dept_ids:
                # Create a default protected department
                if protected_id == 'dept_systems_eng':
                    new_dept = DepartmentGenome(
                        dept_id='dept_systems_eng',
                        name='Systems Engineering',
                        mandate='Core systems engineering and infrastructure',
                        manager=AgentGenome(
                            role='Engineering Manager',
                            goal='Lead systems engineering',
                            backstory='Experienced engineering leader',
                            model_tier='executive'
                        ),
                        agents=[]
                    )
                elif protected_id == 'dept_qa_redteam':
                    new_dept = DepartmentGenome(
                        dept_id='dept_qa_redteam',
                        name='QA & Red Team',
                        mandate='Quality assurance and security verification',
                        manager=AgentGenome(
                            role='QA Lead',
                            goal='Ensure quality and security',
                            backstory='Security and QA expert',
                            model_tier='executive'
                        ),
                        agents=[]
                    )
                else:
                    continue

                # Enable tools for workers in technical departments
                if classify_department_role(new_dept) in TECHNICAL_DEPARTMENTS:
                    for agent in new_dept.agents:
                        agent.tools_enabled = True

                child.departments.append(new_dept)
                current_dept_ids.add(protected_id)

        # Ensure at least 2 departments
        if len(child.departments) < 2:
            # Add a generic department if needed
            generic_dept = DepartmentGenome(
                dept_id='dept_general_ops',
                name='General Operations',
                mandate='General operational support',
                manager=AgentGenome(
                    role='Operations Manager',
                    goal='Support operations',
                    backstory='Operational expert',
                    model_tier='executive'
                ),
                agents=[]
            )
            child.departments.append(generic_dept)

        # 3. Tool enablement for newly spawned technical departments
        # We need to identify which departments are "newly spawned" or modified.
        # Since we don't have explicit "new" tracking, we apply tool enablement 
        # to all technical departments in the child to ensure compliance.
        for dept in child.departments:
            category = classify_department_role(dept)
            if category in TECHNICAL_DEPARTMENTS:
                for agent in dept.agents:
                    agent.tools_enabled = True

        return child


class StructuralCrossoverEngine:
    """Enables genetic crossover between two enterprises with asymmetric departmental topologies."""

    def recombine(
        self,
        parent_a: CompanyGenome,
        parent_b: CompanyGenome,
        child_id: str,
        target_generation: int,
        label: str = 'Recombinant'
    ) -> CompanyGenome:
        """Aligns departments by functional role category and performs allelic crossover.

        Invariants:
          1. Deep-copy isolation: Must never mutate `parent_a` or `parent_b` in-place.
          2. Lineage: Sets `child.company_id = child_id`, `child.generation = target_generation`,
             `child.parent_ids = [parent_a.company_id, parent_b.company_id]`.
          3. Level 3 RSI Code Overlay Inheritance: Merges `code_overlays` from both parents
             such that `child.code_overlays` contains all keys from both parents, with
             `parent_a.code_overlays` taking precedence over `parent_b.code_overlays` on key
             collisions (`{**parent_b.code_overlays, **parent_a.code_overlays}`).
          4. CEO Crossover: Combines and deduplicates `ceo.backstory_traits` from both parents
             (preserving order, capped at 6 traits) and sets `ceo.temperature` to the rounded
             average of `parent_a.ceo.temperature` and `parent_b.ceo.temperature`.
          5. Department Alignment: Aligns departments by `classify_department_role` to recombine
             manager traits/temperatures and interleave specialist agents.
        """
        # 1. Deep-copy isolation
        child = parent_a.copy()

        # 2. Lineage
        child.company_id = child_id
        child.generation = target_generation
        child.parent_ids = [parent_a.company_id, parent_b.company_id]

        # 3. Level 3 RSI Code Overlay Inheritance
        # parent_a takes precedence
        child.code_overlays = {**parent_b.code_overlays, **parent_a.code_overlays}

        # 4. CEO Crossover
        # Combine and deduplicate backstory traits, preserving order, capped at 6
        traits_a = list(parent_a.ceo.backstory_traits)
        traits_b = list(parent_b.ceo.backstory_traits)

        combined_traits = []
        seen = set()
        for trait in traits_a + traits_b:
            if trait not in seen:
                combined_traits.append(trait)
                seen.add(trait)

        child.ceo.backstory_traits = combined_traits[:6]

        # Average temperature
        avg_temp = (parent_a.ceo.temperature + parent_b.ceo.temperature) / 2.0
        child.ceo.temperature = round(avg_temp, 2)

        # 5. Department Alignment
        # Group departments by functional category
        depts_a_by_cat: Dict[str, List[DepartmentGenome]] = {}
        for dept in parent_a.departments:
            cat = classify_department_role(dept)
            if cat not in depts_a_by_cat:
                depts_a_by_cat[cat] = []
            depts_a_by_cat[cat].append(dept)

        depts_b_by_cat: Dict[str, List[DepartmentGenome]] = {}
        for dept in parent_b.departments:
            cat = classify_department_role(dept)
            if cat not in depts_b_by_cat:
                depts_b_by_cat[cat] = []
            depts_b_by_cat[cat].append(dept)

        # Get all unique categories
        all_categories = set(depts_a_by_cat.keys()) | set(depts_b_by_cat.keys())

        new_departments: List[DepartmentGenome] = []

        for cat in all_categories:
            depts_a = depts_a_by_cat.get(cat, [])
            depts_b = depts_b_by_cat.get(cat, [])

            # Determine how many departments to create for this category
            # We take the max count to ensure we don't lose departments
            max_count = max(len(depts_a), len(depts_b))

            for i in range(max_count):
                dept_a = depts_a[i] if i < len(depts_a) else None
                dept_b = depts_b[i] if i < len(depts_b) else None

                if dept_a and dept_b:
                    # Crossover between two departments
                    new_dept = self._crossover_departments(dept_a, dept_b, child_id, i)
                elif dept_a:
                    # Only in A, copy it
                    new_dept = dept_a.copy()
                    new_dept.dept_id = f"{dept_a.dept_id}_recomb_{i}"
                elif dept_b:
                    # Only in B, copy it
                    new_dept = dept_b.copy()
                    new_dept.dept_id = f"{dept_b.dept_id}_recomb_{i}"
                else:
                    continue

                new_departments.append(new_dept)

        child.departments = new_departments

        # Ensure we have at least 2 departments (invariant from morphogenesis, 
        # though not explicitly stated for crossover, it's good practice)
        if len(child.departments) < 2:
            # Add a generic department if needed
            generic_dept = DepartmentGenome(
                dept_id='dept_general_ops',
                name='General Operations',
                mandate='General operational support',
                manager=AgentGenome(
                    role='Operations Manager',
                    goal='Support operations',
                    backstory='Operational expert',
                    model_tier='executive'
                ),
                agents=[]
            )
            child.departments.append(generic_dept)

        return child

    def _crossover_departments(
        self,
        dept_a: DepartmentGenome,
        dept_b: DepartmentGenome,
        child_id: str,
        index: int
    ) -> DepartmentGenome:
        """Performs crossover between two departments of the same functional category."""

        # Create a new department ID
        new_dept_id = f"{dept_a.dept_id}_x_{dept_b.dept_id}_{index}"

        # Crossover Manager
        manager_a = dept_a.manager
        manager_b = dept_b.manager

        if manager_a and manager_b:
            # Combine traits
            traits_a = list(manager_a.backstory_traits)
            traits_b = list(manager_b.backstory_traits)

            combined_traits = []
            seen = set()
            for trait in traits_a + traits_b:
                if trait not in seen:
                    combined_traits.append(trait)
                    seen.add(trait)

            new_manager = AgentGenome(
                role=manager_a.role, # Keep role from A
                goal=manager_a.goal, # Keep goal from A
                backstory=manager_a.backstory, # Keep backstory from A
                backstory_traits=combined_traits[:6],
                temperature=round((manager_a.temperature + manager_b.temperature) / 2.0, 2),
                model_tier=manager_a.model_tier, # Keep tier from A
                tools_enabled=manager_a.tools_enabled or manager_b.tools_enabled,
                system_instructions=manager_a.system_instructions
            )
        elif manager_a:
            new_manager = manager_a.copy()
        elif manager_b:
            new_manager = manager_b.copy()
        else:
            # Should not happen due to schema validation, but fallback
            new_manager = AgentGenome(
                role='Manager',
                goal='Manage department',
                backstory='Default manager',
                model_tier='executive'
            )

        # Interleave Agents
        agents_a = list(dept_a.agents)
        agents_b = list(dept_b.agents)

        new_agents: List[AgentGenome] = []

        # Simple interleaving strategy
        max_agents = max(len(agents_a), len(agents_b))
        for i in range(max_agents):
            if i < len(agents_a):
                new_agents.append(agents_a[i].copy())
            if i < len(agents_b):
                new_agents.append(agents_b[i].copy())

        # Create the new department
        new_dept = DepartmentGenome(
            dept_id=new_dept_id,
            name=dept_a.name, # Keep name from A
            mandate=dept_a.mandate, # Keep mandate from A
            manager=new_manager,
            agents=new_agents,
            delegation_rules=dept_a.delegation_rules
        )

        return new_dept
