    def _generate_stdlib_test_script(self, test_files: List[str]) -> str:
        # Generate a script that imports each test file and runs tests
        lines = [
            "import sys",
            "import unittest",
            "import importlib",
            "import traceback",
            "failed = False",
            "collected = 0",
        ]
        for tf in test_files:
            mod_name = tf[:-3].replace('/', '.').replace('\\', '.')
            if mod_name.endswith('.__init__'):
                mod_name = mod_name[:-9]
            lines.append(f"try:")
            lines.append(f"    mod = importlib.import_module('{mod_name}')")
            lines.append(f"    # Collect bare test functions")
            lines.append(f"    for name in dir(mod):")
            lines.append(f"        if name.startswith('test_'):")
            lines.append(f"            func = getattr(mod, name)")
            lines.append(f"            if callable(func) and func.__code__.co_argcount == 0:")
            lines.append(f"                collected += 1")
            lines.append(f"                try:")
            lines.append(f"                    func()")
            lines.append(f"                except Exception as e:")
            lines.append(f"                    print(f'FAIL: {{name}}: {{e}}')")
            lines.append(f"                    traceback.print_exc()")
            lines.append(f"                    failed = True")
            lines.append(f"    # Collect unittest.TestCase subclasses")
            lines.append(f"    for name in dir(mod):")
            lines.append(f"        cls = getattr(mod, name)")
            lines.append(f"        if isinstance(cls, type) and issubclass(cls, unittest.TestCase) and cls is not unittest.TestCase:")
            lines.append(f"            suite = unittest.TestLoader().loadTestsFromTestCase(cls)")
            lines.append(f"            collected += suite.countTestCases()")
            lines.append(f"            runner = unittest.TextTestRunner(verbosity=0)")
            lines.append(f"            result = runner.run(suite)")
            lines.append(f"            if not result.wasSuccessful():")
            lines.append(f"                failed = True")
            lines.append(f"except ModuleNotFoundError as e:")
            lines.append(f"    print(f'SKIP: {{mod_name}}: {{e}}')")
            lines.append(f"except Exception as e:")
            lines.append(f"    print(f'ERROR: {{mod_name}}: {{e}}')")
            lines.append(f"    traceback.print_exc()")
            lines.append(f"    failed = True")

        lines.append("if collected == 0:")
        lines.append("    print('NO TESTS COLLECTED')")
        lines.append("    sys.exit(1)")
        lines.append("if failed:")
        lines.append("    sys.exit(1)")
        lines.append("sys.exit(0)")

        return "\n".join(lines)

    def _gate_telemetry(self, workdir: str, authored: Dict[str, str]) -> GateResult:
        start = time.time()

        py_files = [p for p in authored if p.endswith('.py')]

        has_import = False
        has_call = False

        tracer_methods = {
            'start_as_current_span', 'start_span', 'get_tracer', 
            'get_tracer_provider', 'set_tracer_provider', 'get_meter'
        }

        for path in py_files:
            content = authored[path]
            try:
                tree = ast.parse(content)
            except SyntaxError:
                continue

            for node in ast.walk(tree):
                # Check for import opentelemetry
                if isinstance(node, ast.Import):
                    for alias in node.names:
                        if alias.name == 'opentelemetry' or alias.name.startswith('opentelemetry.'):
                            has_import = True
                elif isinstance(node, ast.ImportFrom):
                    if node.module == 'opentelemetry' or (node.module and node.module.startswith('opentelemetry.')):
                        has_import = True

                # Check for calls to tracer/span methods
                if isinstance(node, ast.Call):
                    func = node.func
                    # Handle method calls like tracer.start_span()
                    if isinstance(func, ast.Attribute):
                        if func.attr in tracer_methods:
                            has_call = True
                    # Handle function calls like get_tracer()
                    elif isinstance(func, ast.Name):
                        if func.id in tracer_methods:
                            has_call = True

        duration = time.time() - start

        if has_import and has_call:
            return GateResult(
                name='telemetry',
                status=PASSED,
                method='ast_analysis',
                detail='OpenTelemetry import and tracer/span calls found.',
                duration_s=duration
            )

        if not has_import:
            return GateResult(
                name='telemetry',
                status=FAILED,
                method='ast_analysis',
                detail='No OpenTelemetry import found.',
                duration_s=duration
            )

        if not has_call:
            return GateResult(
                name='telemetry',
                status=FAILED,
                method='ast_analysis',
                detail='OpenTelemetry imported but no tracer/span calls found.',
                duration_s=duration
            )

        return GateResult(
            name='telemetry',
            status=FAILED,
            method='ast_analysis',
            detail='Telemetry requirements not met.',
            duration_s=duration
        )

