        count_source_files
    )
except ImportError:
    # Fallback implementation if artifacts module is not yet available or import fails
    # This ensures the harness can run independently for testing if needed,
    # though the spec implies it's a dependency.
    EXCLUDED_DIR_SEGMENTS = ('.pytest_cache', '__pycache__', 'venv', '.venv', '.git', '.mypy_cache', '.ruff_cache', '.tox', 'node_modules', '.ipynb_checkpoints')
    EXCLUDED_DIR_SUFFIXES = ('.egg-info', '.dist-info')

    def is_generated_path(path: str) -> bool:
        parts = path.replace('\\', '/').split('/')
        for part in parts:
            if part in EXCLUDED_DIR_SEGMENTS:
                return True
            if any(part.endswith(s) for s in EXCLUDED_DIR_SUFFIXES):
                return True
        return False

    def is_malformed_path(path: str) -> bool:
        if not path:
            return True
        if path != path.strip():
            return True
        if '*' in path or '`' in path:
            return True
        if path.startswith('-'):
            return True
        if path.endswith('.') or path.endswith('~'):
            return True
        return False

    def sanitize_path(path: str) -> str:
        path = path.strip()
        path = path.replace('*', '').replace('`', '')
        if path.startswith('-'):
            path = path[1:]
        if path.endswith('.') or path.endswith('~'):
            path = path[:-1]
        return path

    def filter_bundle(bundle: Dict[str, str]) -> Dict[str, str]:
        return {k: v for k, v in bundle.items() if not is_generated_path(k) and not is_malformed_path(k)}

    def partition_bundle(bundle: Dict[str, str]) -> Tuple[Dict[str, str], Dict[str, str], Dict[str, str]]:
        authored = {}
        generated = {}
        malformed = {}
        for k, v in bundle.items():
            if is_generated_path(k):
                generated[k] = v
            elif is_malformed_path(k):
                malformed[k] = v
            else:
                authored[k] = v
        return authored, generated, malformed

    def count_source_files(bundle: Dict[str, str], suffixes: Iterable[str] = ('.py',)) -> int:
        count = 0
        for path in bundle:
            if any(path.endswith(s) for s in suffixes):
                count += 1
        return count


@dataclass
class GateResult:
    """Outcome of a single verification gate."""
    name: str
    status: str
    method: str
    detail: str = ''
    duration_s: float = 0.0
    evidence: Dict[str, Any] = field(default_factory=dict)

    @property
    def passed(self) -> bool:
        return self.status == PASSED

    @property
    def evaluated(self) -> bool:
        return self.status != SKIPPED


@dataclass
class VerificationReport:
    """Aggregate result across all gates."""
    gates: List[GateResult]
    score_penalty: float
    authored_files: int
    python_files: int
    source: str = 'bundle'
    harness_version: str = '3.0-execution'

    def gate(self, name: str) -> Optional[GateResult]:
        for g in self.gates:
            if g.name == name:
                return g
        return None

    @property
    def evaluated_gates(self) -> List[GateResult]:
        return [g for g in self.gates if g.evaluated]

    @property
    def passed_gates(self) -> List[GateResult]:
        return [g for g in self.gates if g.passed]

    @property
    def gate_status(self) -> Dict[str, str]:
        """Gate name -> PASSED | FAILED | SKIPPED. The fitness function's input."""
        return {g.name: g.status for g in self.gates}

    @property
    def gate_detail(self) -> Dict[str, str]:
        return {g.name: g.detail for g in self.gates}

    @property
    def pass_rate(self) -> float:
        """Fraction of *evaluated* gates that passed. Skips are excluded."""
        evaluated = self.evaluated_gates
        if not evaluated:
            return 0.0
        passed = [g for g in evaluated if g.passed]
        return len(passed) / len(evaluated)

    def summary(self) -> str:
        lines = [f"Verification Report ({self.source})"]
        lines.append(f"Authored Files: {self.authored_files}, Python Files: {self.python_files}")
        lines.append(f"Score Penalty: {self.score_penalty:.2f}")
        lines.append("Gates:")
        for g in self.gates:
            lines.append(f"  [{g.status.upper():7}] {g.name:10} ({g.method}): {g.detail}")
        return "\n".join(lines)

    def to_dict(self) -> Dict[str, Any]:
        return {
            "gates": [
                {
                    "name": g.name,
                    "status": g.status,
                    "method": g.method,
                    "detail": g.detail,
                    "duration_s": g.duration_s,
                    "evidence": g.evidence
                }
                for g in self.gates
            ],
            "score_penalty": self.score_penalty,
            "authored_files": self.authored_files,
            "python_files": self.python_files,
            "source": self.source,
            "harness_version": self.harness_version,
            "pass_rate": self.pass_rate,
            "gate_status": self.gate_status
        }


def extract_code_blocks(text: str) -> Dict[str, str]:
    """Recovers a path->content map from fenced code blocks in a deliverable.

    A last resort, used only when a firm produced no live workspace. Only the
    contents of fenced blocks are returned; the surrounding prose is discarded
    and never reaches a gate.
    """
    if not text:
        return {}

    # Regex to match fenced code blocks with optional language and optional path hint
    # Pattern: ```[language] [path]\n content \n```
    # We look for blocks that might contain a path in the info string or just assume sequential naming if not present.
    # The spec says "path->content map". Usually, agents write ```python path/to/file.py ... ```

    pattern = r"```(?:\w+)?\s+([^\n]+)\n(.*?)```"
    matches = re.findall(pattern, text, re.DOTALL)

    bundle = {}
    for i, (path_hint, content) in enumerate(matches):
        # Clean up path hint
        path = path_hint.strip()
        # Remove potential markdown artifacts from path if any
        path = sanitize_path(path)

        # If path looks like a filename, use it. Otherwise, generate a name.
        if not path or '/' not in path and '.' not in path:
            # Try to detect if it's just a language tag that got captured?
            # The regex captures everything after the backticks until newline.
            # If the capture is just "python", it's not a path.
            if path in ['python', 'py', 'bash', 'sh', 'json', 'yaml', 'toml']:
                path = f"generated_file_{i}.py"
            else:
                # Assume it's a path
                pass

        # Ensure it ends with .py if it looks like code but has no extension?
        # The spec implies we recover paths. If no path is given, we might need to guess.
        # However, standard agent behavior is to include the path.
        if not path:
            path = f"generated_file_{i}.py"

        # If the path doesn't have an extension, assume .py for code blocks
        if '.' not in path:
            path += '.py'

        bundle[path] = content

    return bundle


class ExecutionHarness:
    """Materializes a workspace bundle and verifies it by actually running it."""

    def __init__(self, timeout_s: int = DEFAULT_TIMEOUT_S, penalty_per_gate: float = DEFAULT_PENALTY_PER_GATE, python_executable: Optional[str] = None):
        self.timeout_s = timeout_s
        self.penalty_per_gate = penalty_per_gate
        self.python_executable = python_executable or sys.executable

    def verify_workspace(self, workspace: Any = None, deliverable_text: str = '') -> VerificationReport:
        """Verifies whatever code a firm actually produced.

        This is the entry point tournaments use. A firm normally writes into a
        live `AgentWorkspace`; if it never did, we fall back to the fenced code
        blocks embedded in its written deliverable.

        `deliverable_text` is *only* mined for code blocks. Its prose is never
        passed to a gate, because the entire point of this harness is that an
        essay about OpenTelemetry cannot satisfy the telemetry gate.
        """
        bundle = {}
        source = 'bundle'

        # Try to get bundle from workspace object
        if workspace is not None:
            # Assume workspace has a method to get files or is a dict
            if hasattr(workspace, 'get_files'):
                bundle = workspace.get_files()
                source = 'workspace'
            elif isinstance(workspace, dict):
                bundle = workspace
                source = 'workspace'
            elif hasattr(workspace, 'files'):
                bundle = workspace.files
                source = 'workspace'

        # Fallback to deliverable text if bundle is empty
        if not bundle and deliverable_text:
            bundle = extract_code_blocks(deliverable_text)
            source = 'deliverable'

        return self.verify_bundle(bundle, source=source)

    def verify_bundle(self, bundle: Dict[str, str], source: str = 'bundle') -> VerificationReport:
        """Verifies an in-memory path->content map by writing it to a temp dir."""
        # Filter bundle to remove generated/malformed paths
        authored_bundle = filter_bundle(bundle)

        # Count files
        authored_files = len(authored_bundle)
        python_files = count_source_files(authored_bundle, suffixes=('.py',))

        # Create temp directory
        with tempfile.TemporaryDirectory() as tmpdir:
            # Write files to disk
            for path, content in authored_bundle.items():
                full_path = os.path.join(tmpdir, path)
                os.makedirs(os.path.dirname(full_path), exist_ok=True)
                with open(full_path, 'w', encoding='utf-8') as f:
                    f.write(content)

            # Run verification on the directory
            return self.verify_directory(tmpdir, authored=authored_bundle, source=source)

    def verify_directory(self, workdir: str, authored: Optional[Dict[str, str]] = None, source: str = 'directory') -> VerificationReport:
        """Verifies an existing workspace directory."""
        if authored is None:
            # Scan directory for files
            authored = {}
            for root, dirs, files in os.walk(workdir):
                # Filter out excluded dirs
                dirs[:] = [d for d in dirs if not is_generated_path(os.path.join(root, d))]
                for file in files:
                    rel_path = os.path.relpath(os.path.join(root, file), workdir)
                    if not is_generated_path(rel_path) and not is_malformed_path(rel_path):
                        full_path = os.path.join(root, file)
                        try:
                            with open(full_path, 'r', encoding='utf-8') as f:
                                authored[rel_path] = f.read()
                        except Exception:
                            pass

        authored_files = len(authored)
        python_files = count_source_files(authored, suffixes=('.py',))

        gates = []

        # 1. Syntax Gate
        gates.append(self._gate_syntax(workdir, authored))

        # 2. Build Gate
        gates.append(self._gate_build(workdir, authored))

        # 3. Smoke Gate
        gates.append(self._gate_smoke(workdir, authored))

        # 4. Tests Gate
        gates.append(self._gate_tests(workdir, authored))

        # 5. Telemetry Gate
        gates.append(self._gate_telemetry(workdir, authored))

        # Calculate penalty
        failed_count = sum(1 for g in gates if g.status == FAILED)
        score_penalty = failed_count * self.penalty_per_gate

        return VerificationReport(
            gates=gates,
            score_penalty=score_penalty,
            authored_files=authored_files,
            python_files=python_files,
            source=source
        )

    def _gate_syntax(self, workdir: str, authored: Dict[str, str]) -> GateResult:
        start = time.time()
        py_files = [p for p in authored if p.endswith('.py')]

        if not py_files:
            return GateResult(
                name='syntax',
                status=FAILED,
                method='ast_parse',
                detail='No Python files found.',
                duration_s=time.time() - start
            )

        errors = []
        for path in py_files:
            content = authored[path]
            try:
                ast.parse(content)
            except SyntaxError as e:
                errors.append(f"{path}: {e}")

        duration = time.time() - start
        if errors:
            return GateResult(
                name='syntax',
                status=FAILED,
                method='ast_parse',
                detail='Syntax errors found: ' + '; '.join(errors[:5]),
                duration_s=duration,
                evidence={'errors': errors}
            )

        return GateResult(
            name='syntax',
            status=PASSED,
            method='ast_parse',
            detail=f"All {len(py_files)} Python files parsed successfully.",
            duration_s=duration
        )

    def _gate_build(self, workdir: str, authored: Dict[str, str]) -> GateResult:
        start = time.time()

        # Check for packaging metadata
        has_pyproject = 'pyproject.toml' in authored
        has_setup_py = 'setup.py' in authored
        has_setup_cfg = 'setup.cfg' in authored

        if not (has_pyproject or has_setup_py or has_setup_cfg):
            return GateResult(
                name='build',
                status=FAILED,
                method='metadata_check',
                detail='No packaging metadata (pyproject.toml, setup.py, setup.cfg) found.',
                duration_s=time.time() - start
            )

        # Validate pyproject.toml if present
        if has_pyproject:
            content = authored['pyproject.toml']
            try:
                data = tomllib.loads(content)
                # Must contain at least one of [project], [build-system], or [tool]
                if not any(k in data for k in ['project', 'build-system', 'tool']):
                    return GateResult(
                        name='build',
                        status=FAILED,
                        method='toml_validation',
                        detail='pyproject.toml is valid TOML but missing required tables ([project], [build-system], [tool]).',
                        duration_s=time.time() - start
                    )
            except Exception as e:
                return GateResult(
                    name='build',
                    status=FAILED,
                    method='toml_validation',
                    detail=f'pyproject.toml is invalid: {e}',
                    duration_s=time.time() - start
                )

        # Attempt pip install
        # Check if pip is available
        try:
            subprocess.run([self.python_executable, '-m', 'pip', '--version'], 
                           capture_output=True, timeout=10, check=True)
        except Exception:
            return GateResult(
                name='build',
                status=SKIPPED,
                method='pip_install',
                detail='pip not available or failed to run.',
                duration_s=time.time() - start
            )

        # Run pip install -e . --no-deps --no-build-isolation
        try:
            result = subprocess.run(
                [self.python_executable, '-m', 'pip', 'install', '-e', '.', '--no-deps', '--no-build-isolation'],
                cwd=workdir,
                capture_output=True,
                text=True,
                timeout=self.timeout_s
            )
            duration = time.time() - start
            if result.returncode == 0:
                return GateResult(
                    name='build',
                    status=PASSED,
                    method='pip_install',
                    detail='Package installed successfully.',
                    duration_s=duration
                )
            else:
                return GateResult(
                    name='build',
                    status=FAILED,
                    method='pip_install',
                    detail=f'pip install failed: {result.stderr}',
                    duration_s=duration,
                    evidence={'stderr': result.stderr, 'stdout': result.stdout}
                )
        except subprocess.TimeoutExpired:
            return GateResult(
                name='build',
                status=FAILED,
                method='pip_install',
                detail='pip install timed out.',
                duration_s=time.time() - start
            )
        except Exception as e:
            return GateResult(
                name='build',
                status=FAILED,
                method='pip_install',
                detail=f'Error running pip install: {e}',
                duration_s=time.time() - start
            )

    def _gate_smoke(self, workdir: str, authored: Dict[str, str]) -> GateResult:
        start = time.time()

        # Find non-test authored modules
        # Exclude test files
        non_test_modules = []
        for path in authored:
            if not path.endswith('.py'):
                continue
            if 'test' in os.path.basename(path).lower():
                continue
            # Convert path to module name
            # Remove .py
            mod_path = path[:-3]
            # Replace / with .
            mod_name = mod_path.replace('/', '.').replace('\\', '.')
            # Handle __init__.py
            if mod_name.endswith('.__init__'):
                mod_name = mod_name[:-9]
            if mod_name:
                non_test_modules.append(mod_name)

        if not non_test_modules:
            return GateResult(
                name='smoke',
                status=FAILED,
                method='import_check',
                detail='No importable non-test modules found.',
                duration_s=time.time() - start
            )

        # Prepare environment
        env = os.environ.copy()
        python_path = env.get('PYTHONPATH', '')
        new_paths = [workdir, os.path.join(workdir, 'src')]
        if python_path:
            env['PYTHONPATH'] = os.pathsep.join(new_paths + [python_path])
        else:
            env['PYTHONPATH'] = os.pathsep.join(new_paths)

        # Try importing each module in a subprocess
        failed_imports = []
        skipped_imports = []

        for mod_name in non_test_modules:
            try:
                # Use subprocess to isolate imports
                code = f"import {mod_name}"
                result = subprocess.run(
                    [self.python_executable, '-c', code],
                    env=env,
                    capture_output=True,
                    text=True,
                    timeout=10
                )
                if result.returncode != 0:
                    stderr = result.stderr
                    # Check for ModuleNotFoundError for third-party packages
                    if 'ModuleNotFoundError' in stderr:
                        # Check if it's a known third-party package (heuristic: not in stdlib, not in workspace)
                        # Simple heuristic: if the missing module is not in the authored files, it's likely third-party
                        # Extract module name from error
                        match = re.search(r"No module named '([^']+)'", stderr)
                        if match:
                            missing_mod = match.group(1)
                            # If the missing module is not part of the workspace, treat as skipped
                            if not any(missing_mod in p for p in authored):
                                skipped_imports.append(mod_name)
                                continue
                    failed_imports.append(f"{mod_name}: {stderr.strip()}")
            except Exception as e:
                failed_imports.append(f"{mod_name}: {e}")

        duration = time.time() - start

        if failed_imports:
            return GateResult(
                name='smoke',
                status=FAILED,
                method='import_check',
                detail='Import failures: ' + '; '.join(failed_imports[:5]),
                duration_s=duration,
                evidence={'failed': failed_imports}
            )

        if skipped_imports and not failed_imports:
            # If all imports were skipped due to missing third-party deps
            return GateResult(
                name='smoke',
                status=SKIPPED,
                method='import_check',
                detail='Imports skipped due to missing third-party dependencies.',
                duration_s=duration,
                evidence={'skipped': skipped_imports}
            )

        return GateResult(
            name='smoke',
            status=PASSED,
            method='import_check',
            detail=f"All {len(non_test_modules)} modules imported successfully.",
            duration_s=duration
        )

    def _gate_tests(self, workdir: str, authored: Dict[str, str]) -> GateResult:
        start = time.time()

        # Discover test files
        test_files = [p for p in authored if 'test' in os.path.basename(p).lower() and p.endswith('.py')]

        if not test_files:
            return GateResult(
                name='tests',
                status=FAILED,
                method='test_discovery',
                detail='No test files found.',
                duration_s=time.time() - start
            )

        # Prepare environment
        env = os.environ.copy()
        python_path = env.get('PYTHONPATH', '')
        new_paths = [workdir, os.path.join(workdir, 'src')]
        if python_path:
            env['PYTHONPATH'] = os.pathsep.join(new_paths + [python_path])
        else:
            env['PYTHONPATH'] = os.pathsep.join(new_paths)

        # Check if pytest is available
        try:
            subprocess.run([self.python_executable, '-m', 'pytest', '--version'], 
                           capture_output=True, timeout=10, check=True)
            has_pytest = True
        except Exception:
            has_pytest = False

        if has_pytest:
            # Run pytest
            try:
                result = subprocess.run(
                    [self.python_executable, '-m', 'pytest', '-v', '--tb=short'],
                    cwd=workdir,
                    env=env,
                    capture_output=True,
                    text=True,
                    timeout=self.timeout_s
                )
                duration = time.time() - start
                if result.returncode == 0:
                    return GateResult(
                        name='tests',
                        status=PASSED,
                        method='pytest',
                        detail='All tests passed.',
                        duration_s=duration
                    )
                else:
                    # Check if failure was due to ModuleNotFoundError
                    if 'ModuleNotFoundError' in result.stderr or 'ModuleNotFoundError' in result.stdout:
                        # Heuristic: if tests failed to collect due to missing deps
                        if 'error' in result.stderr.lower() and 'import' in result.stderr.lower():
                             return GateResult(
                                name='tests',
                                status=SKIPPED,
                                method='pytest',
                                detail='Tests skipped due to missing dependencies.',
                                duration_s=duration,
                                evidence={'stderr': result.stderr}
                            )
                    return GateResult(
                        name='tests',
                        status=FAILED,
                        method='pytest',
                        detail='Tests failed.',
                        duration_s=duration,
                        evidence={'stderr': result.stderr, 'stdout': result.stdout}
                    )
            except subprocess.TimeoutExpired:
                return GateResult(
                    name='tests',
                    status=FAILED,
                    method='pytest',
                    detail='Tests timed out.',
                    duration_s=time.time() - start
                )
            except Exception as e:
                return GateResult(
                    name='tests',
                    status=FAILED,
                    method='pytest',
                    detail=f'Error running pytest: {e}',
                    duration_s=time.time() - start
                )
        else:
            # Stdlib fallback
            # Run a script that imports test files and executes test functions
            test_script = self._generate_stdlib_test_script(test_files)
            try:
                result = subprocess.run(
                    [self.python_executable, '-c', test_script],
                    cwd=workdir,
                    env=env,
                    capture_output=True,
                    text=True,
                    timeout=self.timeout_s
                )
                duration = time.time() - start
                if result.returncode == 0:
                    return GateResult(
                        name='tests',
                        status=PASSED,
                        method='stdlib_fallback',
                        detail='All tests passed.',
                        duration_s=duration
                    )
                else:
                    if 'ModuleNotFoundError' in result.stderr:
                        return GateResult(
                            name='tests',
                            status=SKIPPED,
                            method='stdlib_fallback',
                            detail='Tests skipped due to missing dependencies.',
                            duration_s=duration,
                            evidence={'stderr': result.stderr}
                        )
                    return GateResult(
                        name='tests',
                        status=FAILED,
                        method='stdlib_fallback',
                        detail='Tests failed.',
                        duration_s=duration,
                        evidence={'stderr': result.stderr, 'stdout': result.stdout}
                    )
            except Exception as e:
                return GateResult(
                    name='tests',
                    status=FAILED,
                    method='stdlib_fallback',
                    detail=f'Error running tests: {e}',
                    duration_s=time.time() - start
                )

    def _generate_stdlib_test_script(self, test_files: List[str]) -> str:
        # Generate a script that imports each test file and runs tests
        lines = [
            "import sys",
            "import unittest",
            "import importlib",
            "import traceback",
            "failed = False",
            "collected = 0",
        ]
        for tf in test_files:
            mod_name = tf[:-3].replace('/', '.').replace('\\', '.')
            if mod_name.endswith('.__init__'):
                mod_name = mod_name[:-9]
            lines.append(f"try:")
            lines.append(f"    mod = importlib.import_module('{mod_name}')")
            lines.append(f"    # Collect bare test functions")
            lines.append(f"    for name in dir(mod):")
            lines.append(f"        if name.startswith('test_'):")
            lines.append(f"            func = getattr(mod, name)")
            lines.append(f"            if callable(func) and func.__code__.co_argcount == 0:")
            lines.append(f"                collected += 1")
            lines.append(f"                try:")
            lines.append(f"                    func()")
            lines.append(f"                except Exception as e:")
            lines.append(f"                    print(f'FAIL: {{name}}: {{e}}')")
            lines.append(f"                    traceback.print_exc()")
            lines.append(f"                    failed = True")
            lines.append(f"    # Collect unittest.TestCase subclasses")
            lines.append(f"    for name in dir(mod):")
            lines.append(f"        cls = getattr(mod, name)")
            lines.append(f"        if isinstance(cls, type) and issubclass(cls, unittest.TestCase) and cls is not unittest.TestCase:")
            lines.append(f"            suite = unittest.TestLoader().loadTestsFromTestCase(cls)")
            lines.append(f"            collected += suite.countTestCases()")
            lines.append(f"            runner = unittest.TextTestRunner(verbosity=0)")
            lines.append(f"            result = runner.run(suite)")
            lines.append(f"            if not result.wasSuccessful():")
            lines.append(f"                failed = True")
            lines.append(f"except ModuleNotFoundError as e:")
            lines.append(f"    print(f'SKIP: {{mod_name}}: {{e}}')")
            lines.append(f"except Exception as e:")
            lines.append(f"    print(f'ERROR: {{mod_name}}: {{e}}')")
            lines.append(f"    traceback.print_exc()")
            lines.append(f"    failed = True")

        lines.append("if collected == 0:")
